using System.Text.Json;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Diagnostics;using Microsoft.EntityFrameworkCore.Infrastructure;using StreamForge.Playback.Api.Data;using StreamForge.Playback.Api.Models;using StreamForge.Playback.Api.Services;
namespace StreamForge.Playback.UnitTests;
public sealed class CompletionProjectorTests
{
    [Fact]public async Task V1IsConsumedWithoutProjection(){var factory=Factory();var payload=JsonSerializer.Serialize(new{eventId=Guid.NewGuid(),eventType="video.transcoding.completed",eventVersion=1});await new CompletionProjector(factory,TimeProvider.System).ProjectAsync(new("video-transcoding-completed",0,0,payload),default);await using var db=await factory.CreateDbContextAsync();Assert.Empty(db.Packages);Assert.Single(db.ConsumedMessages);}
    [Fact]public async Task V2ProjectionIsIdempotentByEventId(){var factory=Factory();var videoId=Guid.NewGuid();var eventId=Guid.NewGuid();var prefix=$"videos/{videoId:N}/hls/";var value=new VideoTranscodingCompletedV2(eventId,"video.transcoding.completed",2,DateTimeOffset.UtcNow,Guid.NewGuid(),videoId,"source","key","etag",[],new HlsPackageV2("streamforge-renditions",prefix,prefix+"master.m3u8","etag","fmp4",4,10,100,[new HlsVariantV2("360p",640,360,30,"h264","aac","codecs",800000,700000,prefix+"360p/index.m3u8","etag",3,100)]),"correlation");var projector=new CompletionProjector(factory,TimeProvider.System);var json=JsonSerializer.Serialize(value,new JsonSerializerOptions(JsonSerializerDefaults.Web));await projector.ProjectAsync(new("video-transcoding-completed",0,0,json),default);await projector.ProjectAsync(new("video-transcoding-completed",1,0,json),default);await using var db=await factory.CreateDbContextAsync();Assert.Single(db.Packages);Assert.Single(db.Variants);Assert.Equal(2,db.ConsumedMessages.Count());}
    private static IDbContextFactory<PlaybackDbContext> Factory(){var options=new DbContextOptionsBuilder<PlaybackDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).ConfigureWarnings(x=>x.Ignore(InMemoryEventId.TransactionIgnoredWarning)).Options;return new PooledDbContextFactory<PlaybackDbContext>(options);}
}
